public with sharing class ContactLookupAction {

    @InvocableMethod(Label='Find Contact by Email',
                     Description='Finds the earliest-created contact for each email address.')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>();
        if (requests == null || requests.isEmpty()) {
            return results;
        }

        List<String> normalizedEmails = new List<String>(requests.size());
        for (Request request : requests) {
            String normalizedEmail = normalizeEmail(request == null ? null : request.email);
            normalizedEmails.add(normalizedEmail);
            results.add(new Result());
        }

        Set<String> emailsToQuery = new Set<String>();
        for (String normalizedEmail : normalizedEmails) {
            if (normalizedEmail != null) {
                emailsToQuery.add(normalizedEmail);
            }
        }

        Map<String, Contact> earliestContactByEmail = new Map<String, Contact>();
        if (!emailsToQuery.isEmpty()) {
            List<Contact> contacts = [SELECT Id, Email, CreatedDate
                                      FROM Contact
                                      WHERE Email IN :emailsToQuery
                                      ORDER BY CreatedDate ASC];
            for (Contact contact : contacts) {
                String contactEmail = normalizeEmail(contact.Email);
                if (contactEmail == null) {
                    continue;
                }

                Contact existing = earliestContactByEmail.get(contactEmail);
                if (existing == null || isEarlier(contact, existing)) {
                    earliestContactByEmail.put(contactEmail, contact);
                }
            }
        }

        for (Integer index = 0; index < requests.size(); index++) {
            String normalizedEmail = normalizedEmails.get(index);
            if (normalizedEmail == null) {
                continue;
            }

            Contact contact = earliestContactByEmail.get(normalizedEmail);
            if (contact != null) {
                results.get(index).contactId = contact.Id;
                results.get(index).found = true;
            }
        }

        return results;
    }

    private static String normalizeEmail(String email) {
        if (email == null) {
            return null;
        }

        String trimmed = email.trim();
        if (trimmed == '') {
            return null;
        }

        return trimmed.toLowerCase();
    }

    private static Boolean isEarlier(Contact candidate, Contact existing) {
        if (candidate.CreatedDate == null) {
            return existing.CreatedDate != null;
        }

        if (existing.CreatedDate == null) {
            return true;
        }

        if (candidate.CreatedDate == existing.CreatedDate) {
            return candidate.Id < existing.Id;
        }

        return candidate.CreatedDate < existing.CreatedDate;
    }

    public class Request {
        @InvocableVariable(Label='Email', Required=true)
        public String email;
    }

    public class Result {
        @InvocableVariable(Label='Contact ID')
        public Id contactId;

        @InvocableVariable(Label='Found')
        public Boolean found;
    }
}
