public class AccountScoringJob implements Queueable {
    private List<Id> accountIds;
    private static final Integer BATCH_SIZE = 200;

    public AccountScoringJob() {
        this.accountIds = new List<Id>();
    }

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = (accountIds == null) ? new List<Id>() : accountIds;
    }

    public void execute(Queueable job) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer batchSize = Math.min(BATCH_SIZE, accountIds.size());
        List<Id> batchIds = new List<Id>();

        for (Id id : accountIds.subList(0, batchSize)) {
            if (id != null) {
                batchIds.add(id);
            }
        }

        if (!batchIds.isEmpty()) {
            Account[] accounts = [SELECT Id, AnnualRevenue FROM Account WHERE Id IN :batchIds];

            for (Account account : accounts) {
                if (account.AnnualRevenue != null && account.AnnualRevenue >= 1000000) {
                    account.Rating = 'Hot';
                } else if (account.AnnualRevenue != null && account.AnnualRevenue >= 100000) {
                    account.Rating = 'Warm';
                } else {
                    account.Rating = 'Cold';
                }
            }

            update accounts;
        }

        if (batchSize < accountIds.size()) {
            System.enqueueJob(new AccountScoringJob(accountIds.subList(batchSize, accountIds.size())));
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }

        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
