public with sharing class ErpSyncFinalizer implements Finalizer {
    private static final Integer MAX_ATTEMPTS = 3;
    private static final Integer ERROR_FIELD_LENGTH = 255;

    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds == null ? new Set<Id>() : new Set<Id>(accountIds);
        this.attempt = attempt == null ? 1 : attempt;
    }

    public void execute(FinalizerContext context) {
        Boolean didSucceed = context != null && context.didSucceed();
        String errorMessage = null;

        if (!didSucceed) {
            errorMessage = context == null ? null : context.getExceptionMessage();
            if (errorMessage != null && errorMessage.length() > ERROR_FIELD_LENGTH) {
                errorMessage = errorMessage.left(ERROR_FIELD_LENGTH);
            }
        }

        FB_Job_Log__c jobLog = new FB_Job_Log__c(
            Job_Name__c = 'ErpAccountSyncJob',
            Status__c = didSucceed ? 'Success' : 'Failed',
            Attempt__c = attempt,
            Error__c = errorMessage
        );
        insert jobLog;

        if (!didSucceed && attempt != null && attempt < MAX_ATTEMPTS) {
            try {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            } catch (Exception e) {
                // Do not let a retry-enqueue failure prevent the failure log from being saved.
            }
        }
    }
}
