public class LogPurgeJob implements Schedulable {
    private static final Integer NON_ERROR_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final Integer DELETE_BATCH_SIZE = 50000;

    public LogPurgeJob() {
    }

    public void execute(SchedulableContext context) {
        DateTime now = DateTime.now();
        DateTime nonErrorCutoff = now.addDays(-NON_ERROR_RETENTION_DAYS);
        DateTime errorCutoff = now.addDays(-ERROR_RETENTION_DAYS);

        deleteInBatches(nonErrorCutoff, errorCutoff, DELETE_BATCH_SIZE);
    }

    private static void deleteInBatches(DateTime nonErrorCutoff, DateTime errorCutoff, Integer batchSize) {
        String soql =
            'SELECT Id FROM FB_Integration_Log__c ' +
            'WHERE (CreatedDate < :nonErrorCutoff AND (Level__c != \'ERROR\' OR Level__c = NULL)) ' +
            'OR (CreatedDate < :errorCutoff AND Level__c = \'ERROR\')';

        QueryLocator queryLocator = Database.getQueryLocator(soql);

        while (queryLocator.hasNext()) {
            List<Id> ids = new List<Id>();

            for (Integer i = 0; i < batchSize && queryLocator.hasNext(); i++) {
                ids.add((Id) queryLocator.next().get('Id'));
            }

            if (!ids.isEmpty()) {
                delete ids;
            }
        }
    }

    public static Id scheduleNightly() {
        return System.schedule('Log purge (nightly)', '0 0 2 ? * *', LogPurgeJob.class);
    }
}
