            return new List<Opportunity>();
        }

        fflib_QueryFactory queryFactory = createQuery()
            .addSelectSObjectField(Opportunity.Account.Name);

        queryFactory.setWhereClause('IsClosed = false AND AccountId IN :accountIds');
        queryFactory.setOrderByClause('Amount DESC NULLS LAST, CloseDate ASC NULLS LAST');

        if (maxRecords != null) {
            queryFactory.setLimit(maxRecords);
        }

        return (List<Opportunity>) queryFactory.selectList();
    }
