public class CaseEscalationService {
    public static void escalate(Set<Id> caseIds, String reason) {
        if (reason == null || reason.trim().length() == 0) {
            throw new EscalationException('Escalation reason is required.');
        }

        if (caseIds == null || caseIds.isEmpty()) {
            return;
        }

        List<Case> cases = CasesSelector.newInstance().selectById(caseIds);
        if (cases == null || cases.isEmpty()) {
            return;
        }

        List<Case> casesToEscalate = new List<Case>();
        for (Case c : cases) {
            if (c == null || c.Id == null || c.Status == 'Closed' || c.IsEscalated == true) {
                continue;
            }
            casesToEscalate.add(c);
        }

        if (casesToEscalate.isEmpty()) {
            return;
        }

        fflib_Uow uow = Application.UnitOfWork.newInstance();
        Date activityDate = Date.today().addDays(1);

        for (Case c : casesToEscalate) {
            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            Task task = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = activityDate,
                Priority = 'High'
            );
            uow.registerNew(task);
        }

        uow.commitWork();
    }

    public class EscalationException extends Exception {
        public EscalationException() {
            super('Escalation failed.');
        }

        public EscalationException(String message) {
            super(message);
        }
    }
}
