public class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> accounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return accounts;
        }

        fflib_SObjectUnitOfWork sowu = new fflib_SObjectUnitOfWork();

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            accounts.add(new Account(Name = accountName));
        }

        sowu.insertSObjects(accounts);

        List<Contact> contacts = new List<Contact>();
        for (Account account : accounts) {
            List<String> lastNames = contactLastNamesByAccountName.get(account.Name);
            if (lastNames == null) {
                continue;
            }

            for (String lastName : lastNames) {
                contacts.add(new Contact(LastName = lastName, AccountId = account.Id));
            }
        }

        if (!contacts.isEmpty()) {
            sowu.insertSObjects(contacts);
        }

        sowu.commitWork();

        return accounts;
    }
}
