public class CasePriorityHandler {
    public static void handleBeforeInsert(List<Case> newCases) {
        if (newCases == null || newCases.isEmpty()) {
            return;
        }

        Set<Id> accountIds = new Set<Id>();
        for (Case c : newCases) {
            if (c.AccountId != null) {
                accountIds.add(c.AccountId);
            }
        }

        if (accountIds.isEmpty()) {
            return;
        }

        Map<Id, String> accountRatingsById = new Map<Id, String>();
        for (Account a : [SELECT Id, Rating FROM Account WHERE Id IN :accountIds]) {
            accountRatingsById.put(a.Id, a.Rating);
        }

        for (Case c : newCases) {
            if (c.AccountId != null && 'Hot' == accountRatingsById.get(c.AccountId)) {
                c.Priority = 'High';
            }
        }
    }
}
