/**
 * Applies the pricing team's standard discount to new OpportunityLineItems that do not have an explicit discount.
 *
 * I changed the suggested "call PricingRules.standardDiscountFor(line.Product2Id) for each line" approach
 * because that method performs one SOQL query per Product2. A CPQ quote with 200 line items can therefore
 * perform up to 200 queries in one transaction, exceeding the 100-SOQL governor limit.
 *
 * This handler resolves all needed Product2.Family values in a single bulk SOQL query and then delegates the
 * family-to-discount decision to PricingRules.standardDiscountForFamily. That keeps the actual pricing rules
 * in PricingRules without copying them into this class.
 */
public with sharing class LineItemDiscountHandler {
    public static void beforeInsert(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        Set<Id> productIdsNeedingDiscount = new Set<Id>();
        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDiscount.add(line.Product2Id);
            }
        }

        if (productIdsNeedingDiscount.isEmpty()) {
            return;
        }

        Map<Id, Decimal> standardDiscountByProduct = new Map<Id, Decimal>();
        List<Product2> products = [
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIdsNeedingDiscount
        ];

        for (Product2 product : products) {
            standardDiscountByProduct.put(product.Id, PricingRules.standardDiscountForFamily(product.Family));
        }

        for (OpportunityLineItem line : newLines) {
            if (line.Discount == null && line.Product2Id != null && standardDiscountByProduct.containsKey(line.Product2Id)) {
                line.Discount = standardDiscountByProduct.get(line.Product2Id);
            }
        }
    }
}
