trigger CaseTrigger on Case (after update) {
    // Enqueue survey processing for cases that transition from open to closed and have a contact.
    //
    // Change from the literal “enqueue one job per case” pattern for all cases:
    // Salesforce allows at most 50 Queueable jobs to be enqueued in a single transaction.
    // Nightly cleanup can close up to 200 cases in one transaction, so when more than 50 cases
    // qualify, the trigger enqueues one CaseSurveyJob that fans out individual one-case jobs
    // in safe chunks. This preserves the isolation goal: each case still gets its own job.
    if (Trigger.isAfter && Trigger.isUpdate) {
        List<Id> newlyClosedCaseIds = new List<Id>();

        for (Case c : Trigger.new) {
            Case oldC = Trigger.oldMap.get(c.Id);

            if (c.IsClosed == true
                && oldC != null
                && oldC.IsClosed == false
                && c.ContactId != null) {
                newlyClosedCaseIds.add(c.Id);
            }
        }

        if (!newlyClosedCaseIds.isEmpty()) {
            final Integer MAX_ENQUEUE_PER_TX = 50;

            if (newlyClosedCaseIds.size() <= MAX_ENQUEUE_PER_TX) {
                // Requested behavior: one job per case.
                for (Id caseId : newlyClosedCaseIds) {
                    System.enqueueJob(new CaseSurveyJob(caseId));
                }
            } else {
                // Fan-out scheduler: this job will enqueue one CaseSurveyJob per case,
                // but in chunks that respect the 50 enqueue limit per transaction.
                System.enqueueJob(new CaseSurveyJob(newlyClosedCaseIds));
            }
        }
    }
}
