public with sharing class CaseSurveyJob implements Queueable {
    private Id caseId;
    private List<Id> caseIds;

    private static final Integer MAX_ENQUEUE_PER_TX = 50;
    private static final Integer MAX_INDIVIDUAL_JOBS_WITH_CONTINUATION = 49;

    public CaseSurveyJob(Id caseId) {
        this.caseId = caseId;
    }

    public CaseSurveyJob(List<Id> caseIds) {
        this.caseIds = caseIds == null ? new List<Id>() : caseIds;
    }

    public void execute(QueueableContext context) {
        if (caseId != null) {
            createSurveyTask(caseId);
        } else if (caseIds != null && !caseIds.isEmpty()) {
            enqueuePerCaseJobs();
        }
    }

    private void createSurveyTask(Id caseId) {
        Case cs = [SELECT Id, CaseNumber, ContactId FROM Case WHERE Id = :caseId LIMIT 1];

        if (cs == null || cs.ContactId == null || cs.CaseNumber == null) {
            return;
        }

        Task surveyTask = new Task(
            WhatId = cs.Id,
            WhoId = cs.ContactId,
            Subject = 'CSAT survey: ' + cs.CaseNumber,
            ActivityDate = Date.today().addDays(2),
            Status = 'Not Started'
        );

        insert surveyTask;
    }

    private void enqueuePerCaseJobs() {
        // In one transaction we can enqueue at most 50 Queueable jobs.
        // If more than 50 case IDs remain, enqueue 49 individual jobs plus one continuation
        // job that will enqueue the rest.
        Integer toEnqueue;

        if (caseIds.size() <= MAX_ENQUEUE_PER_TX) {
            toEnqueue = caseIds.size();
        } else {
            toEnqueue = MAX_INDIVIDUAL_JOBS_WITH_CONTINUATION;
        }

        for (Integer i = 0; i < toEnqueue; i++) {
            System.enqueueJob(new CaseSurveyJob(caseIds[i]));
        }

        if (caseIds.size() > toEnqueue) {
            List<Id> remainingIds = new List<Id>();
            for (Integer i = toEnqueue; i < caseIds.size(); i++) {
                remainingIds.add(caseIds[i]);
            }

            System.enqueueJob(new CaseSurveyJob(remainingIds));
        }
    }
}
