public class RenewalReminderService {
    // One Messaging.sendEmail call per opportunity is used to isolate a single failing
    // message. For larger volumes, sending one list of messages and inspecting results is
    // more efficient; use per-call sends when you need to keep going after one message throws.
    private static final Integer MAX_IDS_PER_QUERY = 200;

    public static Integer sendReminders(List<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        Set<Id> uniqueOpportunityIds = new Set<Id>();
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                uniqueOpportunityIds.add(opportunityId);
            }
        }

        if (uniqueOpportunityIds.isEmpty()) {
            return 0;
        }

        List<Id> opportunityIdList = new List<Id>();
        for (Id opportunityId : uniqueOpportunityIds) {
            opportunityIdList.add(opportunityId);
        }

        List<Opportunity> opportunities = new List<Opportunity>();
        for (Integer i = 0; i < opportunityIdList.size(); i += MAX_IDS_PER_QUERY) {
            List<Id> chunk = opportunityIdList.subList(i, Math.min(i + MAX_IDS_PER_QUERY, opportunityIdList.size()));
            opportunities.addAll([
                SELECT Id,
                       Name,
                       CloseDate,
                       OwnerId
                FROM Opportunity
                WHERE Id IN :chunk
            ]);
        }

        Integer sentCount = 0;

        for (Opportunity opportunity : opportunities) {
            if (opportunity.OwnerId == null) {
                continue;
            }

            try {
                Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
                email.setTargetObjectId(opportunity.OwnerId);
                email.setSaveAsActivity(false);

                String opportunityName = opportunity.Name;
                email.setSubject('Renewal due: ' + opportunityName);

                String closeDateText = opportunity.CloseDate == null ? 'not set' : String.valueOf(opportunity.CloseDate);
                email.setPlainTextBody(
                    'The close date for ' + opportunityName + ' is ' + closeDateText + '.'
                );

                Messaging.SendEmailResult[] results = Messaging.sendEmail(new Messaging.SingleEmailMessage[] { email });

                if (results != null && !results.isEmpty() && results[0].isSuccess()) {
                    sentCount++;
                } else {
                    String status = (results != null && !results.isEmpty()) ? results[0].getStatus() : 'No result';
                    System.debug(
                        LoggingLevel.WARN,
                        'RenewalReminderService: email not sent for Opportunity ' + opportunity.Id + ' - ' + status
                    );
                }
            } catch (Exception exception) {
                System.debug(
                    LoggingLevel.ERROR,
                    'RenewalReminderService: failed to send reminder for Opportunity ' + opportunity.Id + ' - ' + exception.getMessage()
                );
            }
        }

        return sentCount;
    }
}
