/**
 * After an Account's BillingCountry changes, update MailingCountry on that
 * account's contacts whose MailingCountry is blank or equal to the account's
 * previous BillingCountry.
 *
 * Changed approach:
 * The requested approach was to query all Contact records in the org into a map.
 * With roughly 2.3 million contacts, that would be extremely slow and would
 * normally exceed the 50,000-record SOQL limit per transaction, especially for
 * 200-account MDM batches.
 *
 * This handler still performs exactly one SOQL query, but only queries contacts
 * for the accounts whose BillingCountry actually changed.
 */
public class AccountCountrySync {
    public static void handle(List<Account> newAccounts, Map<Id, Account> oldAccounts) {
        Map<Id, Account> changedAccounts = new Map<Id, Account>();
        Map<Id, String> previousCountries = new Map<Id, String>();

        for (Account newAccount : newAccounts) {
            Account oldAccount = oldAccounts.get(newAccount.Id);
            if (oldAccount == null) {
                continue;
            }

            if (newAccount.BillingCountry != oldAccount.BillingCountry) {
                changedAccounts.put(newAccount.Id, newAccount);
                previousCountries.put(newAccount.Id, oldAccount.BillingCountry);
            }
        }

        if (changedAccounts.isEmpty()) {
            return;
        }

        Set<Id> changedAccountIds = changedAccounts.keySet();

        List<Contact> contacts = [
            SELECT Id, AccountId, MailingCountry
            FROM Contact
            WHERE AccountId IN :changedAccountIds
        ];

        Map<Id, Contact> contactsToUpdate = new Map<Id, Contact>();

        for (Contact contact : contacts) {
            Account account = changedAccounts.get(contact.AccountId);
            if (account == null) {
                continue;
            }

            String previousCountry = previousCountries.get(contact.AccountId);

            if (isBlank(contact.MailingCountry) || contact.MailingCountry == previousCountry) {
                contact.MailingCountry = account.BillingCountry;
                contactsToUpdate.put(contact.Id, contact);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate.values();
        }
    }

    private static Boolean isBlank(String value) {
        return value == null || value.trim() == '';
    }
}
