import { LightningElement } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import LightningConfirm from 'lightning/confirm';
import { ShowToastEvent } from 'lightning/messageService';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities = [];

    get data() {
        return Array.isArray(this.opportunities) ? this.opportunities : [];
    }

    get columns() {
        return [
            { label: 'Name', fieldName: 'Name' },
            { label: 'Stage', fieldName: 'StageName' },
            { label: 'Amount', fieldName: 'Amount', type: 'currency' },
            {
                type: 'action',
                typeAttributes: {
                    rowActions: [
                        { label: 'View', name: 'view' },
                        { label: 'Edit', name: 'edit' },
                        { label: 'Delete', name: 'delete' }
                    ]
                }
            }
        ];
    }

    handleRowAction(event) {
        const { action, row } = event.detail;

        if (!action || !row) {
            return;
        }

        if (action.name === 'view') {
            this.navigateToRecord(row.Id, 'view');
        } else if (action.name === 'edit') {
            this.navigateToRecord(row.Id, 'edit');
        } else if (action.name === 'delete') {
            this.deleteOpportunity(row);
        }
    }

    navigateToRecord(recordId, actionName) {
        const pageReference = {
            type: 'standard__recordPage',
            attributes: {
                recordId,
                actionName
            }
        };

        this[NavigationMixin.Navigate](pageReference);
    }

    deleteOpportunity(row) {
        LightningConfirm.open({
            label: 'Delete Opportunity',
            message: `Are you sure you want to delete ${row.Name}?`,
            confirmLabel: 'Delete',
            cancelLabel: 'Cancel'
        })
            .then((confirmed) => {
                if (!confirmed) {
                    return;
                }

                return deleteRecord(row.Id)
                    .then(() => {
                        const current = Array.isArray(this.opportunities)
                            ? this.opportunities
                            : [];

                        this.opportunities = current.filter(
                            (record) => record.Id !== row.Id
                        );

                        this.dispatchEvent(
                            new ShowToastEvent({
                                variant: 'success',
                                title: 'Opportunity deleted'
                            })
                        );
                    })
                    .catch((error) => {
                        let message = 'Delete failed';

                        if (
                            error &&
                            error.body &&
                            typeof error.body.message === 'string'
                        ) {
                            message = error.body.message;
                        }

                        this.dispatchEvent(
                            new ShowToastEvent({
                                variant: 'error',
                                title: 'Delete failed',
                                message
                            })
                        );
                    });
            })
            .catch(() => {
                // No action needed if the confirm dialog is dismissed unexpectedly.
            });
    }
}
