import { LightningElement, api } from 'lwc';

export default class StatusListbox extends LightningElement {
    _value = '';
    _options = [];
    _activeIndex = 0;

    @api label = '';

    @api get value() {
        return this._value;
    }

    set value(newValue) {
        this._value = newValue === null || newValue === undefined ? '' : newValue;
        this.syncActiveToSelected();
    }

    @api get options() {
        return this._options;
    }

    set options(newValue) {
        this._options = Array.isArray(newValue) ? newValue : [];
        this.syncActiveToSelected();
    }

    get optionData() {
        const selectedIndex = this.selectedOptionIndex;

        return this._options.map((option, index) => ({
            id: `option-${index}`,
            value: option ? option.value : '',
            label: option ? option.label : '',
            selected: index === selectedIndex ? 'true' : 'false'
        }));
    }

    get selectedOptionIndex() {
        return this._options.findIndex(
            (option) => option && this.isSameValue(option.value, this._value)
        );
    }

    get activeOptionId() {
        const index = this.activeIndex;
        return index >= 0 ? `option-${index}` : '';
    }

    get activeIndex() {
        const count = this._options.length;

        if (count === 0) {
            return -1;
        }

        if (this._activeIndex < 0 || this._activeIndex >= count) {
            return 0;
        }

        return this._activeIndex;
    }

    syncActiveToSelected() {
        const selectedIndex = this.selectedOptionIndex;
        this._activeIndex = selectedIndex >= 0 ? selectedIndex : 0;
    }

    isSameValue(a, b) {
        if (a === b) {
            return true;
        }

        if (a === null || a === undefined || b === null || b === undefined) {
            return false;
        }

        return String(a) === String(b);
    }

    onKeyDown(event) {
        const key = event.key;
        const handledKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

        if (!handledKeys.includes(key)) {
            return;
        }

        event.preventDefault();

        const count = this._options.length;
        if (count === 0) {
            return;
        }

        const activeIndex = this.activeIndex;

        switch (key) {
            case 'ArrowDown':
                if (activeIndex < count - 1) {
                    this._activeIndex = activeIndex + 1;
                }
                break;
            case 'ArrowUp':
                if (activeIndex > 0) {
                    this._activeIndex = activeIndex - 1;
                }
                break;
            case 'Home':
                this._activeIndex = 0;
                break;
            case 'End':
                this._activeIndex = count - 1;
                break;
            case 'Enter':
            case ' ':
                this.selectOption(activeIndex);
                break;
            default:
                break;
        }
    }

    onOptionClick(event) {
        const value = event.currentTarget.dataset.value;
        const index = this._options.findIndex(
            (option) => option && this.isSameValue(option.value, value)
        );

        if (index !== -1) {
            this.selectOption(index);
        }
    }

    selectOption(index) {
        const option = this._options[index];

        if (!option) {
            return;
        }

        this._activeIndex = index;

        if (!this.isSameValue(option.value, this._value)) {
            this._value = option.value;
            this.dispatchEvent(new CustomEvent('change', {
                detail: { value: option.value },
                bubbles: true,
                composed: true
            }));
        }
    }
}
