import { LightningElement, api } from 'lwc';

export default class TaskChecklist extends LightningElement {
    @api heading;
    _tasks = [];
    items = [];
    newLabel = '';
    nextId = 1;

    @api get tasks() {
        return this._tasks;
    }

    @api set tasks(value) {
        if (value === this._tasks) {
            return;
        }
        this._tasks = value;
        this.items = this.copyTasks(value);
    }

    get headingDisplay() {
        return this.heading == null ? '' : String(this.heading).toUpperCase();
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    copyTasks(value) {
        return (Array.isArray(value) ? value : []).map((task) => ({ ...task }));
    }

    handleLabelChange(event) {
        this.newLabel = (event.detail && event.detail.value != null) ? event.detail.value : '';
    }

    handleAdd() {
        const label = (this.newLabel || '').trim();
        if (!label) {
            return;
        }

        this.items = [
            ...this.items,
            {
                id: this.generateId(),
                label,
                done: false
            }
        ];

        this.newLabel = '';
        const input = this.template.querySelector('.new-task');
        if (input) {
            input.value = '';
        }

        this.dispatchEvent(new CustomEvent('taskadded', {
            detail: { label },
            bubbles: true,
            composed: true
        }));
    }

    generateId() {
        let id;
        do {
            id = `new-${Date.now()}-${this.nextId++}`;
        } while (this.items.some((task) => String(task.id) === String(id)));
        return id;
    }

    handleToggle(event) {
        const target = event && event.target;
        if (!target || !target.dataset || target.dataset.id === undefined || target.dataset.id === null) {
            return;
        }

        const id = String(target.dataset.id);
        const nextDone = Boolean(target.checked);

        this.items = this.items.map((task) => (
            String(task.id) === id ? { ...task, done: nextDone } : task
        ));
    }
}
