     * Former with an end date of today.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> employerIds = new Set<Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id normalizedContactId = normalizeId(contactId);
            Id employerId = normalizeId(employerByContactId.get(contactId));

            if (normalizedContactId != null && employerId != null) {
                employerIds.add(employerId);
            }
        }

        if (employerIds.isEmpty()) {
            return;
        }

        // Validate that the supplied employer Account IDs exist and are visible.
        Set<Id> validEmployerIds = new Set<Id>();
        for (Account employer : [SELECT Id FROM Account WHERE Id IN :employerIds]) {
            validEmployerIds.add(normalizeId(employer.Id));
        }

        if (validEmployerIds.isEmpty()) {
            return;
        }

        Map<Id, Id> employerByValidContactId = new Map<Id, Id>();
        for (Id contactId : employerByContactId.keySet()) {
            Id normalizedContactId = normalizeId(contactId);
            Id employerId = normalizeId(employerByContactId.get(contactId));

            if (normalizedContactId != null && employerId != null && validEmployerIds.contains(employerId)) {
                employerByValidContactId.put(normalizedContactId, employerId);
            }
        }

        if (employerByValidContactId.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        for (Contact contact : [SELECT Id, npsp__Primary_Affiliation__c
                                FROM Contact
                                WHERE Id IN :employerByValidContactId.keySet()]) {
            Id employerId = employerByValidContactId.get(normalizeId(contact.Id));
            if (employerId == null) {
                continue;
            }

            Id currentEmployerId = normalizeId(contact.npsp__Primary_Affiliation__c);

            // If the organization is already the primary affiliation, do nothing.
            if (currentEmployerId != employerId) {
                contact.npsp__Primary_Affiliation__c = employerId;
                contactsToUpdate.add(contact);
            }
        }

        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }

    private static Id normalizeId(Id id) {
        if (id == null) {
            return null;
        }

        String s = String.valueOf(id);
        if (s.length() == 18) {
            s = s.substring(0, 15);
        }

        if (s.length() == 15) {
            return Id.valueOf(s);
        }

        return null;
    }
}
