            if (lead == null) {
                continue;
            }

            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
