public class TA_Case_PreventReopen implements TriggerAction.BeforeUpdate {
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Case> oldCaseMap = new Map<Id, Case>();

        for (SObject sObject : triggerOld) {
            Case oldCase = (Case) sObject;
            oldCaseMap.put(oldCase.Id, oldCase);
        }

        for (SObject sObject : triggerNew) {
            Case currentCase = (Case) sObject;
            Case oldCase = oldCaseMap.get(currentCase.Id);

            if (oldCase.Status == 'Closed' && currentCase.Status != 'Closed') {
                currentCase.addError('Closed cases cannot be reopened. Please create a new case.');
            }
        }
    }
}
