public class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        if (triggerNew == null) {
            return;
        }

        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;
        if (accountsById == null) {
            return;
        }

        for (SObject sObj : triggerNew) {
            Contact contact = (Contact) sObj;

            if (contact.AccountId == null) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }

            if (isBlank(contact.MailingStreet) &&
                isBlank(contact.MailingCity) &&
                isBlank(contact.MailingPostalCode) &&
                isBlank(contact.MailingCountry)) {
                contact.MailingStreet = account.BillingStreet;
                contact.MailingCity = account.BillingCity;
                contact.MailingPostalCode = account.BillingPostalCode;
                contact.MailingCountry = account.BillingCountry;
            }
        }
    }

    private static Boolean isBlank(String value) {
        return value == null || value.trim() == '';
    }
}
